+static bk_err_t pm_openvela_clock_validate(void)
+{
+#if CONFIG_OPENVELA_AP_480M
+	uint32_t clk = sys_drv_all_modules_clk_div_get(CLK_DIV_REG0);
+	uint32_t required = bk_pm_vdddig_required_get(PM_CPU_FRQ_480M);
