+static bk_err_t cpu_reset_wait(uint32_t cpu_id, uint32_t released)
+{
+	uint32_t count = 1000;
+
+	while (count--)
+	{
+		uint32_t control = cpu_id == 1 ?
+			sys_ll_get_cpu1_int_halt_clk_op_cpu1_sw_rst() :
+			sys_ll_get_cpu2_int_halt_clk_op_cpu2_sw_rst();
+		uint32_t status = cpu_id == 1 ?
+			sys_ll_get_cpu_current_run_status_cpu1_sw_reset() :
+			sys_ll_get_cpu_current_run_status_cpu2_sw_reset();
+
+		if (control == released && status == released)
+			return BK_OK;
+		bk_delay_us(1);
+	}
+
+	BK_LOGE(NULL, "cpu%d reset %s failed ctrl=0x%x run=0x%x\r\n",
+		cpu_id, released ? "release" : "hold",
+		cpu_id == 1 ? bk_cpu1_ctrl_get() : bk_cpu2_ctrl_get(),
+		bk_cpu_run_status_get());
+	return BK_FAIL;
+}
+
+bk_err_t bk_cpu1_hold_reset(void)
+{
+	sys_drv_set_cpu1_reset(0);
+	return cpu_reset_wait(1, 0);
+}
+
+bk_err_t bk_cpu1_release_reset(uint32_t offset)
+{
+	sys_drv_set_cpu1_pwr_dw(0);
+	sys_drv_set_cpu1_rxevt_sel(1);
+	sys_drv_set_cpu1_boot_address_offset(offset >> 8);
+	sys_drv_set_cpu1_reset(1);
+	return cpu_reset_wait(1, 1);
+}
+
+bk_err_t bk_cpu2_hold_reset(void)
+{
+	sys_drv_set_cpu2_reset(0);
+	return cpu_reset_wait(2, 0);
+}
+
+bool bk_cpu2_reset_is_held(void)
